package ru.bitcoin.node.rvn.pow;

import java.util.Arrays;
import java.util.Objects;

/**
 * Independent test vectors MUST be sourced from Ravencoin Core, not generated by the implementation under test.
 */
public record RvnPowVector(String name, RvnPowAlgorithm algorithm, byte[] raw,
                           byte[] expectedIdWire, byte[] expectedPowWire) {
    public RvnPowVector {
        Objects.requireNonNull(name);
        Objects.requireNonNull(algorithm);
        RvnPowHeaderRules.requireHeader(algorithm, raw);
        if (expectedIdWire == null || expectedIdWire.length != 32 ||
                expectedPowWire == null || expectedPowWire.length != 32)
            throw new IllegalArgumentException("Expected two 32-byte digests");
        raw = raw.clone();
        expectedIdWire = expectedIdWire.clone();
        expectedPowWire = expectedPowWire.clone();
    }

    @Override
    public byte[] raw() {
        return raw.clone();
    }

    @Override
    public byte[] expectedIdWire() {
        return expectedIdWire.clone();
    }

    @Override
    public byte[] expectedPowWire() {
        return expectedPowWire.clone();
    }
}
